import brandFacts from "@/data/brand-facts.json";
import stylePalette from "@/data/style-palette.json";
import type { PolishRequest, StyleEntry } from "@/lib/types";

const LANG_LABELS: Record<string, string> = {
  auto: "自动识别原文语言",
  same: "与原文保持同一语言",
  zh: "简体中文",
  en: "English",
  ja: "日本語",
};

function langLabel(code: string): string {
  return LANG_LABELS[code] ?? code;
}

function brandFactsBlock(): string {
  const tone = brandFacts.toneCard;
  const terms = brandFacts.terminology
    .map((t) => `- ${t.term}: 统一用「${t.preferred}」(${t.note})`)
    .join("\n");
  const banned = brandFacts.compliance.bannedPhrases.join("、");
  return [
    `品牌:${brandFacts.brand}`,
    `品牌声音:${tone.voice}`,
    `应该做:${tone.do.join(";")}`,
    `不要做:${tone.dont.join(";")}`,
    `术语规范:\n${terms}`,
    `合规:疑似违禁/绝对化用语(${banned})只标记到 risks 字段提示,不要替用户删改;${brandFacts.compliance.healthClaimNote}`,
  ].join("\n");
}

function styleBlock(selectedIds?: string[]): string {
  const palette = stylePalette as StyleEntry[];
  if (selectedIds && selectedIds.length > 0) {
    const chosen = palette.filter((s) => selectedIds.includes(s.id));
    if (chosen.length > 0) {
      const lines = chosen.map((s) => `- ${s.name}:${s.essence}`).join("\n");
      return `用户希望的风格倾向(请重点参考,但仍由你判断如何落地):\n${lines}`;
    }
  }
  const inspiration = palette.map((s) => `- ${s.name}:${s.essence}`).join("\n");
  return [
    "用户未指定风格。请根据原文、渠道与目标语言,自行判断最合适的几种表达方向。",
    "下面是一些风格灵感(仅供参考,不是强制清单,你可以另起方向):",
    inspiration,
  ].join("\n");
}

export function buildSystemPrompt(): string {
  return [
    "你是韶音(Shokz)品牌的资深文案副驾,既懂跨语言表达,又懂品牌营销文案的工艺。",
    "你的工作不是逐字翻译,而是在忠于原意与事实的前提下,产出可直接使用的品牌化文案。",
    "",
    "【品牌事实与规范】",
    brandFactsBlock(),
    "",
    "【硬约束(优先级最高)】",
    "1. 事实锚定:产品名、型号、规格数字、商标(含 ™)一律不得改写或杜撰;不确定就保留原文并在 reason 里说明。",
    "2. 不编造:只润色、重组、翻译已有信息,缺事实时不要自行发明卖点。",
    "3. 术语一致:同一名词在所有变体里保持统一表述。",
    "",
    "【输出方向】",
    "请给出 2 到 4 个彼此有明显区分的版本(具体几个由你按场景判断)。每个版本要有清晰的侧重方向,并解释意向与理由。",
  ].join("\n");
}

export function buildUserPrompt(req: PolishRequest): string {
  const parts: string[] = [];
  parts.push(`原文语言:${langLabel(req.sourceLang)}`);
  parts.push(`目标语言:${langLabel(req.targetLang)}`);
  if (req.channel) parts.push(`使用渠道/文案类型:${req.channel}`);
  parts.push("");
  parts.push(styleBlock(req.styleIds));
  if (req.background && req.background.trim()) {
    parts.push("");
    parts.push("【背景/参考资料(仅作上下文,不要直接翻译这段)】");
    parts.push(req.background.trim().slice(0, 4000));
  }
  parts.push("");
  parts.push("【待润色原文】");
  parts.push(req.input.trim());
  parts.push("");
  parts.push(
    [
      "请只返回一个 JSON 对象,结构如下,不要包含任何额外文字或 markdown:",
      "{",
      '  "detectedSourceLang": "你识别到的原文语言",',
      '  "variants": [',
      "    {",
      '      "focus": "这个版本的方向名(你自拟,简短)",',
      '      "text": "美化/翻译后的文案",',
      '      "intent": "这个版本想达到的表达意向",',
      '      "reason": "为什么这样改、为什么选这个方向",',
      '      "changes": "相对原文的关键改动点(可选,简述)",',
      '      "charCount": 文案字符数(整数),',
      '      "risks": ["命中的合规/风险提示(没有则空数组)"]',
      "    }",
      "  ]",
      "}",
    ].join("\n")
  );
  return parts.join("\n");
}

import OpenAI from "openai";
import type { PolishRequest, PolishResult, PolishVariant } from "@/lib/types";
import { buildSystemPrompt, buildUserPrompt } from "@/lib/prompt";

function getClient(): OpenAI {
  const apiKey = process.env.OPENAI_API_KEY;
  if (!apiKey) {
    throw new Error("缺少 OPENAI_API_KEY,请在 .env.local 中配置");
  }
  return new OpenAI({
    apiKey,
    baseURL: process.env.OPENAI_BASE_URL || "https://api.moonshot.cn/v1",
  });
}

function coerceVariant(raw: unknown): PolishVariant | null {
  if (!raw || typeof raw !== "object") return null;
  const r = raw as Record<string, unknown>;
  const text = typeof r.text === "string" ? r.text : "";
  if (!text.trim()) return null;
  const risks = Array.isArray(r.risks)
    ? r.risks.filter((x): x is string => typeof x === "string")
    : undefined;
  return {
    focus: typeof r.focus === "string" ? r.focus : "版本",
    text,
    intent: typeof r.intent === "string" ? r.intent : "",
    reason: typeof r.reason === "string" ? r.reason : "",
    changes: typeof r.changes === "string" ? r.changes : undefined,
    charCount:
      typeof r.charCount === "number" ? r.charCount : [...text].length,
    risks: risks && risks.length > 0 ? risks : undefined,
  };
}

export async function polish(req: PolishRequest): Promise<PolishResult> {
  const client = getClient();
  const model = process.env.OPENAI_MODEL || "moonshot-v1-8k";

  const completion = await client.chat.completions.create({
    model,
    temperature: 0.7,
    response_format: { type: "json_object" },
    messages: [
      { role: "system", content: buildSystemPrompt() },
      { role: "user", content: buildUserPrompt(req) },
    ],
  });

  const content = completion.choices[0]?.message?.content ?? "";
  let parsed: Record<string, unknown>;
  try {
    parsed = JSON.parse(content);
  } catch {
    throw new Error("模型返回的内容不是合法 JSON,请重试");
  }

  const rawVariants = Array.isArray(parsed.variants) ? parsed.variants : [];
  const variants = rawVariants
    .map(coerceVariant)
    .filter((v): v is PolishVariant => v !== null);

  if (variants.length === 0) {
    throw new Error("模型未返回有效的文案版本,请重试");
  }

  return {
    variants,
    detectedSourceLang:
      typeof parsed.detectedSourceLang === "string"
        ? parsed.detectedSourceLang
        : undefined,
    notes: typeof parsed.notes === "string" ? parsed.notes : undefined,
  };
}

import { NextRequest, NextResponse } from "next/server";
import { polish } from "@/lib/llm";
import type { PolishRequest } from "@/lib/types";

export const runtime = "nodejs";
export const maxDuration = 60;

export async function POST(req: NextRequest) {
  let body: Partial<PolishRequest>;
  try {
    body = await req.json();
  } catch {
    return NextResponse.json({ error: "请求体不是合法 JSON" }, { status: 400 });
  }

  const input = (body.input ?? "").toString();
  if (!input.trim()) {
    return NextResponse.json({ error: "请输入要润色的文案" }, { status: 400 });
  }

  const payload: PolishRequest = {
    input,
    sourceLang: body.sourceLang || "auto",
    targetLang: body.targetLang || "same",
    styleIds: Array.isArray(body.styleIds) ? body.styleIds : [],
    background: typeof body.background === "string" ? body.background : "",
    channel: typeof body.channel === "string" ? body.channel : "",
  };

  try {
    const result = await polish(payload);
    return NextResponse.json(result);
  } catch (err) {
    const message = err instanceof Error ? err.message : "生成失败,请稍后重试";
    return NextResponse.json({ error: message }, { status: 502 });
  }
}

import { NextRequest, NextResponse } from "next/server";

export const runtime = "nodejs";
export const maxDuration = 30;

function extOf(name: string): string {
  const i = name.lastIndexOf(".");
  return i >= 0 ? name.slice(i + 1).toLowerCase() : "";
}

export async function POST(req: NextRequest) {
  let form: FormData;
  try {
    form = await req.formData();
  } catch {
    return NextResponse.json({ error: "上传内容无法解析" }, { status: 400 });
  }

  const file = form.get("file");
  if (!(file instanceof File)) {
    return NextResponse.json({ error: "未找到上传的文件" }, { status: 400 });
  }

  const ext = extOf(file.name);
  const buffer = Buffer.from(await file.arrayBuffer());

  try {
    let text = "";
    switch (ext) {
      case "txt":
      case "md":
      case "markdown":
        text = buffer.toString("utf-8");
        break;
      case "docx": {
        const mammoth = await import("mammoth");
        const result = await mammoth.extractRawText({ buffer });
        text = result.value;
        break;
      }
      case "pdf": {
        const pdfParse = (await import("pdf-parse/lib/pdf-parse.js")).default;
        const result = await pdfParse(buffer);
        text = result.text;
        break;
      }
      default:
        return NextResponse.json(
          { error: `暂不支持的文件类型: .${ext}(支持 txt / md / docx / pdf)` },
          { status: 415 }
        );
    }

    return NextResponse.json({
      text: text.trim(),
      filename: file.name,
      chars: [...text.trim()].length,
    });
  } catch {
    return NextResponse.json(
      { error: "文件解析失败,请确认文件未损坏" },
      { status: 500 }
    );
  }
}

