"use client";

import { useState } from "react";
import type { StyleEntry } from "@/lib/types";
import palette from "@/data/style-palette.json";

interface Props {
  selected: string[];
  onToggle: (id: string) => void;
}

export default function StylePalette({ selected, onToggle }: Props) {
  const [open, setOpen] = useState(false);
  const entries = palette as StyleEntry[];
  const groups = Array.from(new Set(entries.map((e) => e.group)));

  return (
    <div className="rounded-lg border border-gray-200 bg-white">
      <button
        type="button"
        onClick={() => setOpen((v) => !v)}
        className="flex w-full items-center justify-between px-4 py-3 text-left text-sm font-medium text-ink"
      >
        <span>
          风格调色板
          <span className="ml-2 font-normal text-ink-faint">
            {selected.length > 0 ? `已选 ${selected.length} 项` : "可选,不选则由模型自判"}
          </span>
        </span>
        <span className="text-ink-faint">{open ? "收起" : "展开"}</span>
      </button>
      {open && (
        <div className="border-t border-gray-100 px-4 py-3">
          {groups.map((g) => (
            <div key={g} className="mb-3 last:mb-0">
              <div className="mb-1.5 text-xs font-medium text-ink-faint">{g}</div>
              <div className="flex flex-wrap gap-2">
                {entries
                  .filter((e) => e.group === g)
                  .map((e) => {
                    const active = selected.includes(e.id);
                    return (
                      <button
                        key={e.id}
                        type="button"
                        title={e.essence}
                        onClick={() => onToggle(e.id)}
                        className={
                          "rounded-full border px-3 py-1 text-xs transition " +
                          (active
                            ? "border-brand bg-brand-soft text-brand-dark"
                            : "border-gray-300 bg-white text-ink-soft hover:border-brand")
                        }
                      >
                        {e.name}
                      </button>
                    );
                  })}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

"use client";

import { useRef, useState } from "react";

interface Props {
  label: string;
  hint?: string;
  onParsed: (text: string, filename: string) => void;
}

export default function FileDropzone({ label, hint, onParsed }: Props) {
  const inputRef = useRef<HTMLInputElement>(null);
  const [status, setStatus] = useState<string>("");
  const [busy, setBusy] = useState(false);

  async function handleFile(file: File) {
    setBusy(true);
    setStatus(`正在解析 ${file.name} …`);
    try {
      const form = new FormData();
      form.append("file", file);
      const res = await fetch("/api/parse", { method: "POST", body: form });
      const data = await res.json();
      if (!res.ok) {
        setStatus(data.error || "解析失败");
        return;
      }
      onParsed(data.text, data.filename);
      setStatus(`已载入 ${data.filename}(${data.chars} 字)`);
    } catch {
      setStatus("解析请求失败");
    } finally {
      setBusy(false);
    }
  }

  return (
    <div>
      <input
        ref={inputRef}
        type="file"
        accept=".txt,.md,.markdown,.docx,.pdf"
        className="hidden"
        onChange={(e) => {
