"use client";

import { useState } from "react";
import LanguageSelector from "@/components/LanguageSelector";
import StylePalette from "@/components/StylePalette";
import FileDropzone from "@/components/FileDropzone";
import ResultCard from "@/components/ResultCard";
import type { PolishResult } from "@/lib/types";

const CHANNELS = ["不限", "电商 listing", "社媒帖", "广告语", "邮件 EDM", "包装文案"];

export default function Home() {
  const [input, setInput] = useState("");
  const [source, setSource] = useState("auto");
  const [target, setTarget] = useState("same");
  const [channel, setChannel] = useState("不限");
  const [styleIds, setStyleIds] = useState<string[]>([]);
  const [background, setBackground] = useState("");
  const [bgName, setBgName] = useState("");

  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [result, setResult] = useState<PolishResult | null>(null);

  function toggleStyle(id: string) {
    setStyleIds((prev) =>
      prev.includes(id) ? prev.filter((x) => x !== id) : [...prev, id]
    );
  }

  async function run() {
    if (!input.trim()) {
      setError("请先输入要润色的文案");
      return;
    }
    setLoading(true);
    setError("");
    setResult(null);
    try {
      const res = await fetch("/api/polish", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          input,
          sourceLang: source,
          targetLang: target,
          styleIds,
          background,
          channel: channel === "不限" ? "" : channel,
        }),
      });
      const data = await res.json();
      if (!res.ok) {
        setError(data.error || "生成失败");
        return;
      }
      setResult(data as PolishResult);
    } catch {
      setError("请求失败,请检查网络或稍后重试");
    } finally {
      setLoading(false);
    }
  }

  return (
    <main className="mx-auto max-w-6xl px-4 py-6">
      <header className="mb-6 flex flex-wrap items-center justify-between gap-3">
        <div>
          <h1 className="text-xl font-bold text-ink">文案副驾</h1>
          <p className="text-sm text-ink-faint">品牌文案润色与跨语言美化 · 韶音</p>
        </div>
        <LanguageSelector
          source={source}
          target={target}
          onSourceChange={setSource}
          onTargetChange={setTarget}
        />
      </header>

      <div className="grid grid-cols-1 gap-5 md:grid-cols-2">
        <section className="space-y-3">
          <div className="flex items-center gap-2">
            <label className="text-sm text-ink-soft">渠道</label>
            <select
              value={channel}
              onChange={(e) => setChannel(e.target.value)}
              className="rounded-md border border-gray-300 bg-white px-3 py-1.5 text-sm focus:border-brand focus:outline-none focus:ring-1 focus:ring-brand"
            >
              {CHANNELS.map((c) => (
                <option key={c} value={c}>
                  {c}
                </option>
              ))}
            </select>
          </div>

          <textarea
            value={input}
            onChange={(e) => setInput(e.target.value)}
            placeholder="在此输入要润色或翻译的文案…"
            className="h-64 w-full resize-y rounded-lg border border-gray-300 bg-white p-3 text-[15px] leading-relaxed text-ink focus:border-brand focus:outline-none focus:ring-1 focus:ring-brand"
          />
          <div className="text-right text-xs text-ink-faint">
            {[...input].length} 字
          </div>

          <FileDropzone
            label="上传待润色文档"
            hint="txt / md / docx / pdf"
            onParsed={(text) => setInput(text)}
          />

          <StylePalette selected={styleIds} onToggle={toggleStyle} />

          <FileDropzone
            label="上传背景 / 参考资料"
            hint="品牌调性、卖点、受众等(作上下文)"
            onParsed={(text, name) => {
              setBackground(text);
              setBgName(name);
            }}
          />
          {bgName && (
            <p className="text-xs text-ink-faint">
              背景资料:{bgName}
              <button
                type="button"
                className="ml-2 text-brand-dark"
                onClick={() => {
                  setBackground("");
                  setBgName("");
                }}
              >
                移除
              </button>
            </p>
          )}

          <button
            type="button"
            onClick={run}
            disabled={loading}
            className="w-full rounded-lg bg-brand px-4 py-3 text-center text-sm font-semibold text-white transition hover:bg-brand-dark disabled:opacity-60"
          >
            {loading ? "正在生成…" : "美化文案"}
          </button>
          {error && <p className="text-sm text-red-600">{error}</p>}
        </section>

        <section className="space-y-3">
          {loading && (
            <div className="space-y-3">
              {[0, 1, 2].map((i) => (
                <div
                  key={i}
                  className="h-32 animate-pulse rounded-xl border border-gray-200 bg-white"
                />
              ))}
            </div>
          )}

          {!loading && !result && (
            <div className="flex h-64 items-center justify-center rounded-xl border border-dashed border-gray-300 bg-white text-sm text-ink-faint">
              美化结果会显示在这里,数量由模型按场景判断
            </div>
          )}

          {!loading && result && (
            <>
              {result.detectedSourceLang && (
                <p className="text-xs text-ink-faint">
                  识别原文语言:{result.detectedSourceLang}
                </p>
              )}
              {result.variants.map((v, i) => (
                <ResultCard key={i} variant={v} index={i} />
              ))}
            </>
          )}
        </section>
      </div>
    </main>
  );
}

