/**
 * 抓取 Shokz 官网若干页面的可见文本,落到 data/scrape-raw/ 供人工整理进 brand-facts.json。
 * 注意:官网多为 JS 渲染,纯 fetch 取到的内容有限,产出仅作整理参考,需人工把关。
 * 运行: npm run scrape
 */
import { mkdir, writeFile } from "node:fs/promises";
import { join } from "node:path";

const URLS = [
  "https://shokz.com/",
  "https://www.shokz.com.cn/",
  "https://shokz.com/pages/bone-conduction",
];

function stripHtml(html: string): string {
  return html
    .replace(/<script[\s\S]*?<\/script>/gi, " ")
    .replace(/<style[\s\S]*?<\/style>/gi, " ")
    .replace(/<[^>]+>/g, " ")
    .replace(/&nbsp;/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

async function main() {
  const outDir = join(process.cwd(), "data", "scrape-raw");
  await mkdir(outDir, { recursive: true });

  for (const url of URLS) {
    try {
      const res = await fetch(url, {
        headers: { "User-Agent": "Mozilla/5.0 (corpus-curation-bot)" },
      });
      const html = await res.text();
      const text = stripHtml(html);
      const name = url.replace(/https?:\/\//, "").replace(/[^\w.-]+/g, "_") + ".txt";
      await writeFile(join(outDir, name), `# ${url}\n\n${text}\n`, "utf-8");
      console.log(`saved ${name} (${text.length} chars)`);
    } catch (err) {
      console.error(`failed ${url}:`, err);
    }
  }
  console.log("完成。请人工把 data/scrape-raw/ 的内容整理进 data/brand-facts.json。");
}

main();

