const BANNED: string[] = brandFacts.compliance?.bannedPhrases ?? [];

// 规格类数字模式:这些最容易被模型编造
const SPEC_PATTERNS: RegExp[] = [
  /IP\d{2}/gi,
  /\d+\s*(?:小时|个小时|hours?|hrs?)/gi,
  /\d+\s*mAh/gi,
  /\d+\s*(?:克|grams?)/gi,
  /\d+\s*%/g,
  /\d+\s*(?:dB|分贝)/gi,
];

function buildSourceText(req: PolishRequest): string {
  return (
    req.input +
    " " +
    (req.background ?? "") +
    " " +
    JSON.stringify(brandFacts)
  ).toLowerCase();
}

function scanGuards(variant: PolishVariant, sourceText: string): PolishVariant {
  const risks = variant.risks ? [...variant.risks] : [];

  const bannedHits = BANNED.filter((p) => variant.text.includes(p));
  if (bannedHits.length > 0) {
    const flag = `可能含广告法绝对化用语: ${bannedHits.join("、")}`;
    if (!risks.includes(flag)) risks.push(flag);
  }

  const fabricated = new Set<string>();
  for (const pat of SPEC_PATTERNS) {
    const matches = variant.text.match(pat);
    if (!matches) continue;
    for (const m of matches) {
      const num = m.match(/\d+/)?.[0];
      if (num && !sourceText.includes(num.toLowerCase())) {
        fabricated.add(m.trim());
      }
    }
  }
  if (fabricated.size > 0) {
    risks.push(`可能编造的规格/数字(原文未出现): ${[...fabricated].join("、")}`);
  }

  return risks.length > 0 ? { ...variant, risks } : variant;
}

