"use client";

const SOURCE_LANGS = [
  { code: "auto", label: "自动识别" },
  { code: "zh", label: "中文" },
  { code: "en", label: "English" },
  { code: "ja", label: "日本語" },
];

const TARGET_LANGS = [
  { code: "same", label: "保持原语言" },
  { code: "zh", label: "中文" },
  { code: "en", label: "English" },
  { code: "ja", label: "日本語" },
];

interface Props {
  source: string;
  target: string;
  onSourceChange: (v: string) => void;
  onTargetChange: (v: string) => void;
  onSwap: () => void;
}

const selectClass =
  "w-full bg-transparent px-3 py-2.5 text-sm font-medium text-ink focus:outline-none cursor-pointer";

export default function LanguageSelector({
  source,
  target,
  onSourceChange,
  onTargetChange,
  onSwap,
}: Props) {
  const canSwap = source !== "auto" && target !== "same";

  return (
    <div className="flex items-stretch border-b border-gray-200">
      <div className="flex-1">
        <select
          className={selectClass}
          value={source}
          onChange={(e) => onSourceChange(e.target.value)}
          aria-label="源语言"
        >
          {SOURCE_LANGS.map((l) => (
            <option key={l.code} value={l.code}>
              {l.label}
            </option>
          ))}
        </select>
      </div>

      <button
        type="button"
        onClick={onSwap}
        disabled={!canSwap}
        title={canSwap ? "交换语言" : "自动识别 / 保持原语言时无法交换"}
        className="flex w-10 items-center justify-center text-ink-faint transition hover:text-brand disabled:opacity-30"
        aria-label="交换语言"
      >
        ⇄
      </button>

      <div className="flex-1">
        <select
