}

"use client";

import { useEffect, useState } from "react";
import LanguageSelector from "@/components/LanguageSelector";
import StylePalette from "@/components/StylePalette";
import FileDropzone from "@/components/FileDropzone";
import ResultCard from "@/components/ResultCard";
import type { PolishResult } from "@/lib/types";

const CHANNELS = ["不限", "电商 listing", "社媒帖", "广告语", "邮件 EDM", "包装文案"];

export default function Home() {
  const [input, setInput] = useState("");
  const [source, setSource] = useState("auto");
  const [target, setTarget] = useState("same");
  const [channel, setChannel] = useState("不限");
  const [styleIds, setStyleIds] = useState<string[]>([]);
  const [background, setBackground] = useState("");
  const [bgName, setBgName] = useState("");

  const [loading, setLoading] = useState(false);
  const [elapsed, setElapsed] = useState(0);
  const [error, setError] = useState("");
  const [result, setResult] = useState<PolishResult | null>(null);

  useEffect(() => {
    if (!loading) return;
    setElapsed(0);
    const t = setInterval(() => setElapsed((s) => s + 1), 1000);
    return () => clearInterval(t);
  }, [loading]);

  function toggleStyle(id: string) {
    setStyleIds((prev) =>
      prev.includes(id) ? prev.filter((x) => x !== id) : [...prev, id]
    );
  }

  function swapLangs() {
    if (source === "auto" || target === "same") return;
    setSource(target);
    setTarget(source);
  }

  async function run() {
    if (!input.trim()) {
      setError("请先输入要润色的文案");
      return;
    }
    setLoading(true);
    setError("");
    setResult(null);
    try {
      const res = await fetch("/api/polish", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          input,
          sourceLang: source,
          targetLang: target,
          styleIds,
          background,
          channel: channel === "不限" ? "" : channel,
        }),
      });
      const data = await res.json();
      if (!res.ok) {
        setError(data.error || "生成失败");
        return;
      }
      setResult(data as PolishResult);
    } catch {
      setError("请求失败,请检查网络或稍后重试");
    } finally {
      setLoading(false);
    }
  }

  return (
    <main className="mx-auto max-w-5xl px-4 py-8">
      <header className="mb-6">
        <h1 className="text-2xl font-bold tracking-tight text-ink">文案副驾</h1>
        <p className="mt-0.5 text-sm text-ink-faint">品牌文案润色与跨语言美化 · 韶音</p>
      </header>

      {/* 主面板:单一容器,左右分隔 */}
      <div className="overflow-hidden rounded-2xl border border-gray-200 bg-white shadow-sm">
        <LanguageSelector
          source={source}
          target={target}
          onSourceChange={setSource}
          onTargetChange={setTarget}
          onSwap={swapLangs}
        />

        <div className="grid grid-cols-1 divide-y divide-gray-200 md:grid-cols-2 md:divide-x md:divide-y-0">
          {/* 左:输入 */}
          <div className="flex min-h-[440px] flex-col">
            <textarea
              value={input}
              onChange={(e) => setInput(e.target.value)}
              placeholder="键入要润色或翻译的文案…"
              className="flex-1 resize-none border-0 bg-transparent p-5 text-[17px] leading-relaxed text-ink placeholder:text-ink-faint focus:outline-none focus:ring-0"
            />
            <div className="flex items-center gap-3 border-t border-gray-100 px-4 py-2.5">
              <FileDropzone
                variant="inline"
                label="上传文档"
                onParsed={(text) => setInput(text)}
              />
              <span className="text-xs text-ink-faint">{[...input].length} 字</span>
              <button
                type="button"
                onClick={run}
                disabled={loading}
                className="ml-auto rounded-lg bg-brand px-5 py-2 text-sm font-semibold text-white transition hover:bg-brand-dark disabled:opacity-60"
              >
                {loading ? "生成中…" : "美化文案"}
              </button>
            </div>
          </div>

          {/* 右:结果 */}
          <div className="min-h-[440px] bg-gray-50/40 p-5">
            {loading && (
              <div className="space-y-3">
                <div className="flex items-center gap-2 text-sm text-brand-dark">
                  <span className="h-2 w-2 animate-ping rounded-full bg-brand" />
                  正在生成…已等待 {elapsed}s(模型较慢,通常 10–40 秒)
                </div>
                {[0, 1, 2].map((i) => (
                  <div
                    key={i}
                    className="h-28 animate-pulse rounded-xl border border-gray-200 bg-white"
                  />
                ))}
              </div>
            )}

            {!loading && !result && !error && (
              <div className="flex h-full min-h-[380px] items-center justify-center text-center text-sm text-ink-faint">
                美化结果会显示在这里
                <br />
                数量由模型按场景判断
              </div>
            )}

            {!loading && error && (
              <div className="flex h-full min-h-[380px] items-center justify-center text-sm text-red-600">
                {error}
              </div>
            )}

            {!loading && result && (
              <div className="space-y-3">
                {result.detectedSourceLang && (
                  <p className="text-xs text-ink-faint">
                    识别原文语言:{result.detectedSourceLang}
                  </p>
                )}
                {result.variants.map((v, i) => (
                  <ResultCard key={i} variant={v} index={i} />
                ))}
              </div>
            )}
          </div>
        </div>
      </div>

      {/* 选项区:渠道 / 风格 / 背景 */}
      <div className="mt-4 space-y-3">
        <div className="flex flex-wrap items-center gap-3">
          <label className="text-sm text-ink-soft">渠道</label>
          <select
            value={channel}
            onChange={(e) => setChannel(e.target.value)}
            className="rounded-lg border border-gray-200 bg-white px-3 py-2 text-sm focus:border-brand focus:outline-none focus:ring-1 focus:ring-brand"
          >
            {CHANNELS.map((c) => (
              <option key={c} value={c}>
                {c}
              </option>
            ))}
          </select>

          <div className="ml-auto flex items-center gap-2">
            <FileDropzone
              variant="inline"
              label="上传背景资料"
              onParsed={(text, name) => {
                setBackground(text);
                setBgName(name);
              }}
            />
            {bgName && (
              <span className="text-xs text-ink-faint">
                {bgName}
                <button
                  type="button"
                  className="ml-1 text-brand-dark"
                  onClick={() => {
                    setBackground("");
                    setBgName("");
                  }}
                >
                  移除
                </button>
              </span>
            )}
          </div>
        </div>

        <StylePalette selected={styleIds} onToggle={toggleStyle} />
      </div>
    </main>
  );
}

"use client";

import { useRef, useState } from "react";

interface Props {
  label: string;
  hint?: string;
  variant?: "box" | "inline";
  onParsed: (text: string, filename: string) => void;
}

export default function FileDropzone({
  label,
  hint,
  variant = "box",
  onParsed,
}: Props) {
  const inputRef = useRef<HTMLInputElement>(null);
  const [status, setStatus] = useState<string>("");
  const [busy, setBusy] = useState(false);

  async function handleFile(file: File) {
    setBusy(true);
    setStatus(`正在解析 ${file.name} …`);
    try {
      const form = new FormData();
      form.append("file", file);
      const res = await fetch("/api/parse", { method: "POST", body: form });
      const data = await res.json();
      if (!res.ok) {
        setStatus(data.error || "解析失败");
        return;
      }
      onParsed(data.text, data.filename);
      setStatus(`已载入 ${data.filename}(${data.chars} 字)`);
    } catch {
      setStatus("解析请求失败");
    } finally {
      setBusy(false);
    }
  }

  const fileInput = (
    <input
      ref={inputRef}
      type="file"
      accept=".txt,.md,.markdown,.docx,.pdf"
      className="hidden"
      onChange={(e) => {
        const f = e.target.files?.[0];
        if (f) handleFile(f);
        e.target.value = "";
      }}
    />
  );

  if (variant === "inline") {
    return (
      <span className="inline-flex items-center">
        {fileInput}
        <button
          type="button"
          disabled={busy}
          onClick={() => inputRef.current?.click()}
          className="inline-flex items-center gap-1 text-sm text-ink-soft transition hover:text-brand disabled:opacity-60"
          title="支持 txt / md / docx / pdf"
        >
          <span aria-hidden>📎</span>
          {busy ? "解析中…" : label}
        </button>
      </span>
    );
  }

  return (
    <div>
      {fileInput}
      <button
        type="button"
        disabled={busy}
        onClick={() => inputRef.current?.click()}
        className="w-full rounded-lg border border-dashed border-gray-300 bg-white px-4 py-3 text-left text-sm text-ink-soft transition hover:border-brand disabled:opacity-60"
      >
        <span className="font-medium text-ink">{label}</span>
        {hint && <span className="ml-2 text-ink-faint">{hint}</span>}
      </button>
      {status && <p className="mt-1 text-xs text-ink-faint">{status}</p>}
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";

// 代表模型的处理过程(对应 prompt 让它做的事),非真实 token,做轻量氛围用
const PHRASES = [
  "读懂原文的语气和意图…",
  "盘几种不同的表达方向…",
  "对照韶音的腔调打磨措辞…",
  "检查有没有夸大或编造…",
  "整理成几个可选版本…",
];

export default function ThinkingIndicator() {
  const [text, setText] = useState("");
  const [pi, setPi] = useState(0);

  useEffect(() => {
    const phrase = PHRASES[pi % PHRASES.length];
    let i = 0;
    let timer: ReturnType<typeof setTimeout>;
    const typeNext = () => {
      if (i <= phrase.length) {
        setText(phrase.slice(0, i));
        i++;
        timer = setTimeout(typeNext, 50);
      } else {
        timer = setTimeout(() => setPi((p) => p + 1), 1200);
      }
    };
    typeNext();
    return () => clearTimeout(timer);
  }, [pi]);

  return (
    <div className="flex items-center gap-2 text-sm text-ink-soft">
      <span className="flex gap-1">
        <span className="h-1.5 w-1.5 animate-bounce rounded-full bg-brand [animation-delay:-0.3s]" />
        <span className="h-1.5 w-1.5 animate-bounce rounded-full bg-brand [animation-delay:-0.15s]" />
        <span className="h-1.5 w-1.5 animate-bounce rounded-full bg-brand" />
      </span>
      <span className="text-ink">
        {text}
        <span className="animate-pulse text-brand">▋</span>
      </span>
    </div>
  );
}

