const SPEC_PATTERNS: RegExp[] = [
  /IP\d{2}/gi,
  /\d+[\s-]*(?:小时|个小时|hours?|hrs?)/gi,
  /\d+[\s-]*mAh/gi,
  /\d+[\s-]*(?:克|grams?)/gi,
  /\d+\s*%/g,
  /\d+[\s-]*(?:dB|分贝)/gi,
];

export function buildSourceText(input: string, background?: string): string {
  return (
    input +
    " " +
    (background ?? "") +
    " " +
    JSON.stringify(brandFacts)
  ).toLowerCase();
}

export function applyGuards(
  variant: PolishVariant,
  sourceText: string
): PolishVariant {
  const risks = variant.risks ? [...variant.risks] : [];

  const bannedHits = BANNED.filter((p) => variant.text.includes(p));
  if (bannedHits.length > 0) {
    const flag = `可能含广告法绝对化用语: ${bannedHits.join("、")}`;
    if (!risks.includes(flag)) risks.push(flag);
  }

  const fabricated = new Set<string>();
  for (const pat of SPEC_PATTERNS) {
    const matches = variant.text.match(pat);
    if (!matches) continue;
    for (const m of matches) {
      const num = m.match(/\d+/)?.[0];
      if (num && !sourceText.includes(num.toLowerCase())) {
        fabricated.add(m.trim());
      }
    }
  }
  if (fabricated.size > 0) {
    risks.push(`可能编造的规格/数字(原文未出现): ${[...fabricated].join("、")}`);
  }

  return risks.length > 0 ? { ...variant, risks } : variant;
}

export function coerceVariant(raw: unknown): PolishVariant | null {
  if (!raw || typeof raw !== "object") return null;
  const r = raw as Record<string, unknown>;
  const text = typeof r.text === "string" ? r.text : "";
  if (!text.trim()) return null;
  const risks = Array.isArray(r.risks)
    ? r.risks.filter((x): x is string => typeof x === "string")
    : undefined;
  return {
    focus: typeof r.focus === "string" ? r.focus : "版本",
    text,
    intent: typeof r.intent === "string" ? r.intent : "",
    reason: typeof r.reason === "string" ? r.reason : "",
    changes: typeof r.changes === "string" ? r.changes : undefined,
    charCount: typeof r.charCount === "number" ? r.charCount : [...text].length,
    risks: risks && risks.length > 0 ? risks : undefined,
  };
}

import type { PolishVariant } from "@/lib/types";
import { coerceVariant } from "@/lib/guards";

// 从流式累积的(可能不完整的)JSON 文本里,提取已经闭合的 variant 对象
export function extractVariants(buf: string): PolishVariant[] {
  const out: PolishVariant[] = [];
  const key = buf.indexOf('"variants"');
  if (key < 0) return out;
  const arrStart = buf.indexOf("[", key);
  if (arrStart < 0) return out;

  let depth = 0;
  let objStart = -1;
  let inStr = false;
  let esc = false;

  for (let i = arrStart + 1; i < buf.length; i++) {
    const c = buf[i];
    if (inStr) {
      if (esc) esc = false;
      else if (c === "\\") esc = true;
      else if (c === '"') inStr = false;
      continue;
    }
    if (c === '"') {
      inStr = true;
    } else if (c === "{") {
      if (depth === 0) objStart = i;
      depth++;
    } else if (c === "}") {
      depth--;
      if (depth === 0 && objStart >= 0) {
        try {
          const obj = JSON.parse(buf.slice(objStart, i + 1));
          const v = coerceVariant(obj);
          if (v) out.push(v);
        } catch {
          // 对象还没闭合好,跳过
        }
        objStart = -1;
      }
    } else if (c === "]" && depth === 0) {
      break;
    }
  }
  return out;
}

export function extractDetectedLang(buf: string): string | undefined {
  const m = buf.match(/"detectedSourceLang"\s*:\s*"([^"]*)"/);
  return m ? m[1] : undefined;
}

import OpenAI from "openai";
import type { PolishRequest } from "@/lib/types";
import { buildSystemPrompt, buildUserPrompt } from "@/lib/prompt";
import { modelForMode } from "@/lib/models";

function getClient(): OpenAI {
  const apiKey = process.env.OPENAI_API_KEY;
  if (!apiKey) {
    throw new Error("缺少 OPENAI_API_KEY,请在 .env.local 中配置");
  }
  return new OpenAI({
    apiKey,
    baseURL: process.env.OPENAI_BASE_URL || "https://api.moonshot.cn/v1",
    timeout: 120000,
    maxRetries: 1,
  });
}

// 创建流式补全:边生成边吐 token,前端逐张渲染卡片
export async function createPolishStream(req: PolishRequest) {
  const client = getClient();
  const model = modelForMode(req.mode);

  return client.chat.completions.create({
    model,
    temperature: 1,
    max_tokens: 1500,
    response_format: { type: "json_object" },
    stream: true,
    messages: [
      { role: "system", content: buildSystemPrompt() },
      { role: "user", content: buildUserPrompt(req) },
    ],
  });
}

import { NextRequest, NextResponse } from "next/server";
import { createPolishStream } from "@/lib/llm";
import type { PolishRequest } from "@/lib/types";

export const runtime = "nodejs";
export const maxDuration = 120;

export async function POST(req: NextRequest) {
  let body: Partial<PolishRequest>;
  try {
    body = await req.json();
  } catch {
    return NextResponse.json({ error: "请求体不是合法 JSON" }, { status: 400 });
  }

  const input = (body.input ?? "").toString();
  if (!input.trim()) {
    return NextResponse.json({ error: "请输入要润色的文案" }, { status: 400 });
  }

  const payload: PolishRequest = {
    input,
    sourceLang: body.sourceLang || "auto",
    targetLang: body.targetLang || "same",
    styleIds: Array.isArray(body.styleIds) ? body.styleIds : [],
    background: typeof body.background === "string" ? body.background : "",
    channel: typeof body.channel === "string" ? body.channel : "",
    mode: typeof body.mode === "string" ? body.mode : "normal",
  };

  let stream;
  try {
    stream = await createPolishStream(payload);
  } catch (err) {
    const message = err instanceof Error ? err.message : "生成失败,请稍后重试";
    return NextResponse.json({ error: message }, { status: 502 });
  }

  const encoder = new TextEncoder();
  const readable = new ReadableStream({
    async start(controller) {
      try {
        for await (const part of stream) {
          const delta = part.choices?.[0]?.delta?.content ?? "";
          if (delta) controller.enqueue(encoder.encode(delta));
        }
      } catch {
        // 流中断:已发出的内容前端仍可解析,这里直接结束
      } finally {
        controller.close();
      }
    },
  });

  return new Response(readable, {
    headers: {
      "Content-Type": "text/plain; charset=utf-8",
      "Cache-Control": "no-cache, no-transform",
    },
  });
}

