input.new_string:
  setLoading(true);
  setError("");
  setResult(null);
  const sourceText = buildSourceText(input, background);
  try {
    const res = await fetch("/api/polish", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        input,
        sourceLang: source,
        targetLang: target,
        styleIds,
        background,
        channel: channel === "不限" ? "" : channel,
        mode,
      }),
    });

    if (!res.ok || !res.body) {
      const data = await res.json().catch(() => ({}));
      setError(data.error || "生成失败");
      return;
    }

    const reader = res.body.getReader();
    const decoder = new TextDecoder();
    let buf = "";
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      buf += decoder.decode(value, { stream: true });
      const variants = extractVariants(buf).map((v) =>
        applyGuards(v, sourceText)
      );
      if (variants.length > 0) {
        setResult({
          variants,
          detectedSourceLang: extractDetectedLang(buf),
        });
      }
    }

    // 流结束后做一次权威解析,纠正增量解析的可能误差
    try {
      const full = JSON.parse(buf);
      const variants = Array.isArray(full.variants)
        ? full.variants
            .map((v: unknown) => v)
            .filter(Boolean)
            .map((v: PolishResult["variants"][number]) =>
              applyGuards(v, sourceText)
            )
        : [];
      if (variants.length > 0) {
        setResult({ variants, detectedSourceLang: full.detectedSourceLang });
      } else if (extractVariants(buf).length === 0) {
        setError("模型未返回有效的文案版本,请重试");
      }
    } catch {
      if (extractVariants(buf).length === 0) {
        setError("生成结果解析失败,请重试");
      }
    }
  } catch {
    setError("请求失败,请检查网络或稍后重试");
  } finally {
    setLoading(false);
  }
}

