import { extractVariants } from "../lib/parseStream.ts";

async function run(mode) {
  const t0 = Date.now();
  const res = await fetch("http://localhost:3000/api/polish", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      input: "让运动更自由",
      sourceLang: "zh",
      targetLang: "en",
      styleIds: [],
      channel: "广告语",
      mode,
    }),
  });
  if (!res.ok || !res.body) {
    console.log(mode, "HTTP", res.status, await res.text());
    return;
  }
  const reader = res.body.getReader();
  const dec = new TextDecoder();
  let buf = "";
  let firstAt = null;
  let lastCount = 0;
  while (true) {
    const { done, value } = await reader.read();
    if (done) break;
    buf += dec.decode(value, { stream: true });
    const n = extractVariants(buf).length;
    if (n > lastCount) {
      const sec = ((Date.now() - t0) / 1000).toFixed(1);
      if (firstAt === null) firstAt = sec;
      console.log(`  第 ${n} 张卡 @ ${sec}s`);
      lastCount = n;
    }
  }
  const total = ((Date.now() - t0) / 1000).toFixed(1);
  console.log(`${mode}: 首张 ${firstAt}s | 共 ${lastCount} 张 | 总耗时 ${total}s`);
}

await run("fast");

