export function extractDetectedLang(buf: string): string | undefined {
  const m = buf.match(/"detectedSourceLang"\s*:\s*"([^"]*)"/);
  return m ? m[1] : undefined;
}

function unquote(s: string): string {
  try {
    return JSON.parse('"' + s + '"');
  } catch {
    return s;
  }
}

// 完整变体 + 正在生成中那条(只要它的 text 已经写完就先返回,解释随后补)
export function extractStreaming(buf: string): PolishVariant[] {
  const complete = extractVariants(buf);

  const key = buf.indexOf('"variants"');
  if (key < 0) return complete;
  const arrStart = buf.indexOf("[", key);
  if (arrStart < 0) return complete;

  // 找到最后一个已闭合对象的位置,其后即为"正在生成中"的对象
  let depth = 0;
  let inStr = false;
  let esc = false;
  let lastClose = arrStart;
  for (let i = arrStart + 1; i < buf.length; i++) {
    const c = buf[i];
    if (inStr) {
      if (esc) esc = false;
      else if (c === "\\") esc = true;
      else if (c === '"') inStr = false;
      continue;
    }
    if (c === '"') inStr = true;
    else if (c === "{") depth++;
    else if (c === "}") {
      depth--;
      if (depth === 0) lastClose = i;
    } else if (c === "]" && depth === 0) {
      return complete; // 数组已结束,无半成品
    }
  }

  const tail = buf.slice(lastClose + 1);
  const textM = tail.match(/"text"\s*:\s*"((?:[^"\\]|\\.)*)"/);
  if (!textM) return complete;
  const text = unquote(textM[1]);
  if (!text.trim()) return complete;

  const focusM = tail.match(/"focus"\s*:\s*"((?:[^"\\]|\\.)*)"/);
  const focus = focusM ? unquote(focusM[1]) : "版本";

  return [
    ...complete,
    { focus, text, intent: "", reason: "", charCount: [...text].length },
  ];
}

