async function run(mode) {
  const t0 = Date.now();
  let res;
  try {
    res = await fetch("http://localhost:3000/api/polish", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        input: "让运动更自由,享受每一次呼吸",
        sourceLang: "zh",
        targetLang: "en",
        styleIds: [],
        channel: "广告语",
        mode,
      }),
    });
  } catch (e) {
    console.log(`${mode}: 请求异常 ${e.message}`);
    return;
  }
  if (!res.ok || !res.body) {
    console.log(`${mode}: HTTP ${res.status}`, await res.text().catch(() => ""));
    return;
  }
  const reader = res.body.getReader();
  const dec = new TextDecoder();
  let frameBuf = "";
  let content = "";
  let reasoningLen = 0;
  let firstAt = null;
  let last = 0;
  while (true) {
    const { done, value } = await reader.read();
    if (done) break;
    frameBuf += dec.decode(value, { stream: true });
    let nl;
    while ((nl = frameBuf.indexOf("\n")) >= 0) {
      const line = frameBuf.slice(0, nl);
      frameBuf = frameBuf.slice(nl + 1);
      if (!line) continue;
      try {
        const o = JSON.parse(line);
        if (o.c) content += o.c;
        if (o.r) reasoningLen += o.r.length;
      } catch {
        content += line;
      }
    }
    const n = extractStreaming(content).length;
    if (n > last) {
      const s = ((Date.now() - t0) / 1000).toFixed(1);
      if (firstAt === null) firstAt = s;
      last = n;
    }
  }
  let total = ((Date.now() - t0) / 1000).toFixed(1);
  let finalCount = 0;
  try {
    finalCount = JSON.parse(content).variants?.length ?? last;
  } catch {
    finalCount = last;
  }
  console.log(
    `${mode.padEnd(7)} | 首屏 ${firstAt}s | 总 ${total}s | 变体 ${finalCount} | 思考流字符 ${reasoningLen}`
  );
}

