// 创建流式补全:边生成边吐 token,前端逐张渲染卡片
export async function createPolishStream(req: PolishRequest) {
  const client = getClient();
  const model = modelForMode(req.mode);

  // k2.5/k2.6 是思考型模型,默认开启的"思考"会生成数千字 reasoning,导致 3 分钟级延迟。
  // 官方 API 只能开/关思考(不能调强度),故关闭思考以提速——基座模型仍最强。
  // 约束:思考关闭时 temperature 必须 0.6;v1-8k 非思考型,用 1。
  const isKimiThinking = model.startsWith("kimi-k2");

  const params: Record<string, unknown> = {
    model,
    max_tokens: 8000,
    response_format: { type: "json_object" },
    stream: true,
    messages: [
      { role: "system", content: buildSystemPrompt() },
      { role: "user", content: buildUserPrompt(req) },
    ],
  };

  if (isKimiThinking) {
    params.thinking = { type: "disabled" };
    params.temperature = 0.6;
  } else {
    params.temperature = 1;
  }

  return client.chat.completions.create(
    params as Parameters<typeof client.chat.completions.create>[0]
  );
}

